import{_ as t,o as s,c as o,ag as a}from"./chunks/framework.BPmc_f4o.js";const u=JSON.parse('{"title":"Remote Access","description":"Access Muxit from other computers on your network — or anywhere via VPN.","frontmatter":{"title":"Remote Access","description":"Access Muxit from other computers on your network — or anywhere via VPN."},"headers":[],"relativePath":"guides/remote-access.md","filePath":"guides/remote-access.md"}'),i={name:"guides/remote-access.md"};function r(n,e,l,d,c,h){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="remote-access" tabindex="-1">Remote Access <a class="header-anchor" href="#remote-access" aria-label="Permalink to &quot;Remote Access&quot;">​</a></h1><p>Access Muxit from other computers on your network — or anywhere via VPN.</p><div class="tip custom-block"><p class="custom-block-title">Paid feature</p><p>Remote access is available from the <strong>Maker</strong> tier upward. On the Free tier the toggle is disabled in Settings and the server stays bound to <code>localhost</code>; Bonjour/mDNS advertisements are also held back, so nothing leaks onto the LAN. Open <strong>Settings → Subscription</strong> to upgrade.</p></div><h2 id="quick-setup-lan" tabindex="-1">Quick Setup (LAN) <a class="header-anchor" href="#quick-setup-lan" aria-label="Permalink to &quot;Quick Setup (LAN)&quot;">​</a></h2><ol><li>Open <strong>Settings &gt; Remote Access</strong> in the Muxit UI</li><li>Toggle <strong>Enable Remote Access</strong> on</li><li>Set a <strong>password</strong> (min 8 characters, must include uppercase, lowercase, and a digit)</li><li><strong>Restart</strong> the Muxit server</li><li>Open <code>http://&lt;server-ip&gt;:8765</code> on another computer</li><li>Enter your password — done!</li></ol><blockquote><p><strong>Tip:</strong> Find your server&#39;s IP address with <code>ipconfig</code> (Windows).</p></blockquote><p>Until a password is set, other computers are refused — every API call gets <code>401</code> and the login page says a password is needed. Turning remote access on without one does not open anything.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Local (localhost)</th><th>Remote (LAN)</th></tr></thead><tbody><tr><td>Password required</td><td>No</td><td>Yes</td></tr><tr><td>Auth token</td><td>Auto-fetched</td><td>Obtained via login</td></tr><tr><td>WebSocket</td><td>Connects automatically</td><td>Connects after login</td></tr><tr><td>All APIs</td><td>Full access</td><td>Full access after login</td></tr><tr><td>Editor mode</td><td>Works if enabled</td><td>Works if enabled</td></tr></tbody></table><p><strong>Local access is never affected.</strong> When accessing Muxit from the same machine (localhost/127.0.0.1), everything works exactly as before — no password, no login page.</p><h2 id="https-optional" tabindex="-1">HTTPS (Optional) <a class="header-anchor" href="#https-optional" aria-label="Permalink to &quot;HTTPS (Optional)&quot;">​</a></h2><p>Enable <strong>HTTPS (Self-Signed)</strong> in Settings for encrypted connections:</p><ul><li>A self-signed certificate is generated automatically on first use</li><li>Your browser will show a security warning — click &quot;Advanced&quot; &gt; &quot;Accept the Risk&quot; (once per browser)</li><li>All traffic (including your password) is encrypted over the network</li><li>The certificate is stored in <code>workspace/config/muxit.pfx</code></li></ul><p><strong>When to use HTTPS:</strong></p><ul><li>Shared/untrusted network</li><li>Sensitive data passes through Muxit (API keys, instrument data)</li><li>Prevent password sniffing on the LAN</li></ul><p><strong>When HTTP is fine:</strong></p><ul><li>Private home/lab network with trusted users</li></ul><h2 id="settings-reference" tabindex="-1">Settings Reference <a class="header-anchor" href="#settings-reference" aria-label="Permalink to &quot;Settings Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Config Path</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Remote Access</td><td><code>security.remoteAccess</code></td><td><code>false</code></td><td>Bind to 0.0.0.0 (all interfaces). Requires <strong>Maker</strong> — on Free, the flag is honoured in config but overridden to loopback at startup.</td></tr><tr><td>HTTPS</td><td><code>security.https</code></td><td><code>false</code></td><td>Enable HTTPS with self-signed cert</td></tr><tr><td>Bind Address</td><td><code>security.bindAddress</code></td><td><code>127.0.0.1</code></td><td>Override bind address (advanced)</td></tr><tr><td>Extra host names</td><td><code>security.hostnames</code></td><td><code>[]</code></td><td>Extra names browsers may use to reach Muxit — see <a href="#host-names">Host names</a></td></tr></tbody></table><p>These can also be set directly in <code>workspace/config/server.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;security&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;editorMode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;remoteAccess&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;https&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;bindAddress&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="host-names" tabindex="-1">Host Names <a class="header-anchor" href="#host-names" aria-label="Permalink to &quot;Host Names&quot;">​</a></h2><p>Muxit only answers to names it knows are its own. A request whose <code>Host</code> header names anything else is refused with <code>403</code> and <code>&quot;code&quot;: &quot;HOST_NOT_ALLOWED&quot;</code> before it reaches anything else — the API, the WebSocket, <code>/mcp</code>, even the page itself.</p><p>This is what stops <strong>DNS rebinding</strong>: a website you visit points its own domain at <code>127.0.0.1</code> and then talks to Muxit &quot;from the same origin&quot;. Every other check sees a same-origin request from the local machine; the name in the <code>Host</code> header is the one thing that gives it away.</p><p>Always allowed:</p><ul><li><code>localhost</code> (and <code>*.localhost</code>), <code>127.0.0.1</code>, <code>[::1]</code> — on any port</li><li>the IP address the request arrived on, e.g. <code>http://192.168.1.20:8765</code> or a Tailscale IP</li><li>the names you list in <code>security.hostnames</code></li></ul><p>Also allowed when remote access is on:</p><ul><li>this machine&#39;s host name (<code>LAB-PC</code>), <code>LAB-PC.local</code>, and its DNS domain name (<code>lab-pc.corp.example.com</code>) if it has one</li><li>the mDNS name, <code>muxit.local</code> by default (see <a href="#network-discovery-bonjour-mdns">Network Discovery</a>)</li></ul><p>Anything else — a Tailscale MagicDNS name like <code>lab-pc.tail1234.ts.net</code>, a tunnel&#39;s public name, a reverse proxy&#39;s name, a public IP your router forwards — has to be listed, under <strong>Settings &gt; Remote Access &gt; Extra host names</strong> or in <code>server.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;security&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;hostnames&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lab-pc.tail1234.ts.net&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;*.lab.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>*.example.com</code> covers every subdomain of a domain <strong>you control</strong> (not <code>example.com</code> itself). A bare <code>&quot;*&quot;</code> or a wildcard over one label such as <code>&quot;*.com&quot;</code> is ignored with a warning: either would let any website back in. Restart the server after changing the list; the startup banner prints the names it accepts.</p><p>Programs that connect to <code>127.0.0.1</code> or <code>localhost</code> — the CLI, MCP clients, Python scripts — are not affected.</p><h2 id="network-discovery-bonjour-mdns" tabindex="-1">Network Discovery (Bonjour/mDNS) <a class="header-anchor" href="#network-discovery-bonjour-mdns" aria-label="Permalink to &quot;Network Discovery (Bonjour/mDNS)&quot;">​</a></h2><p>When remote access is enabled, Muxit can advertise itself on your local network using mDNS (also known as Bonjour). This lets any device on the LAN find the server at <code>muxit.local</code> without needing to know the IP address.</p><h3 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h3><ol><li>Enable <strong>Remote Access</strong> (see above)</li><li>Open <strong>Settings &gt; Server &gt; Network Discovery</strong></li><li>Toggle <strong>Enable mDNS</strong> on (enabled by default)</li><li>Optionally change the <strong>Hostname</strong> (default: <code>muxit</code>)</li><li><strong>Restart</strong> the server</li></ol><p>Other devices on the network can now reach Muxit at <code>http://muxit.local:8765</code>.</p><h3 id="clean-url-no-port" tabindex="-1">Clean URL (No Port) <a class="header-anchor" href="#clean-url-no-port" aria-label="Permalink to &quot;Clean URL (No Port)&quot;">​</a></h3><p>To access the server as just <code>http://muxit.local</code> (no port number), set the server port to <strong>80</strong>:</p><ul><li>In the GUI: set <strong>Server Port</strong> to <code>80</code></li><li>Or in <code>server.json</code>: <code>&quot;websocket&quot;: { &quot;port&quot;: 80 }</code></li></ul><h3 id="multiple-instances" tabindex="-1">Multiple Instances <a class="header-anchor" href="#multiple-instances" aria-label="Permalink to &quot;Multiple Instances&quot;">​</a></h3><p>If you run multiple Muxit servers on the same network, give each a unique hostname:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;discovery&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;hostname&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;muxit-lab2&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This server will be reachable at <code>muxit-lab2.local</code>.</p><h3 id="settings-reference-1" tabindex="-1">Settings Reference <a class="header-anchor" href="#settings-reference-1" aria-label="Permalink to &quot;Settings Reference&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Config Path</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Enable mDNS</td><td><code>discovery.enabled</code></td><td><code>true</code></td><td>Advertise the server via mDNS</td></tr><tr><td>Hostname</td><td><code>discovery.hostname</code></td><td><code>muxit</code></td><td>The <code>.local</code> hostname to advertise</td></tr></tbody></table><h3 id="how-it-works-1" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works-1" aria-label="Permalink to &quot;How It Works&quot;">​</a></h3><p>Muxit uses mDNS (multicast DNS, RFC 6762) to respond to <code>.local</code> hostname queries on the LAN. It also advertises an <code>_http._tcp</code> service for DNS-SD (service discovery), so network browsers and IoT tools can find it automatically.</p><p>mDNS is supported natively on Windows 10+.</p><h2 id="security-details" tabindex="-1">Security Details <a class="header-anchor" href="#security-details" aria-label="Permalink to &quot;Security Details&quot;">​</a></h2><h3 id="authentication-flow" tabindex="-1">Authentication Flow <a class="header-anchor" href="#authentication-flow" aria-label="Permalink to &quot;Authentication Flow&quot;">​</a></h3><ol><li><strong>Local user</strong> opens Muxit → token auto-fetched from <code>/api/auth/token</code> (loopback-only) → connected</li><li><strong>Remote user</strong> opens Muxit → token fetch returns 403 → login page shown → password submitted → session token issued → connected</li></ol><h3 id="session-tokens" tabindex="-1">Session Tokens <a class="header-anchor" href="#session-tokens" aria-label="Permalink to &quot;Session Tokens&quot;">​</a></h3><ul><li>Valid for 24 hours</li><li>Stored in browser <code>sessionStorage</code> (cleared when tab closes)</li><li>One session per login (multiple tabs share the same session)</li></ul><h3 id="rate-limiting" tabindex="-1">Rate Limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate Limiting&quot;">​</a></h3><p>Failed login attempts are rate-limited to 5 per minute per IP address. After 5 failed attempts, the IP is blocked for 60 seconds.</p><h3 id="password-storage" tabindex="-1">Password Storage <a class="header-anchor" href="#password-storage" aria-label="Permalink to &quot;Password Storage&quot;">​</a></h3><p>Passwords are hashed using PBKDF2 (SHA-256, 100K iterations) with a random salt. The hash is stored in <code>workspace/config/security.json</code> — the plaintext password is never saved.</p><h3 id="writes-must-come-from-muxit-s-own-pages" tabindex="-1">Writes Must Come From Muxit&#39;s Own Pages <a class="header-anchor" href="#writes-must-come-from-muxit-s-own-pages" aria-label="Permalink to &quot;Writes Must Come From Muxit&#39;s Own Pages&quot;">​</a></h3><p>Any website you visit in the same browser can send requests to Muxit&#39;s address, and they arrive looking like local traffic. Muxit therefore refuses any request that <strong>changes</strong> something — creating a script, editing a connector, adding an account, restarting the server — when the browser says it came from a different site. Reading is unaffected.</p><p>This is invisible in normal use, and it does not apply to tools that aren&#39;t browsers: the CLI, MCP clients and scripts using the WebSocket API send no browser origin and are unaffected.</p><p>It does affect one case: <strong>driving Muxit from your own web page served from a different address.</strong> Those writes will be refused. Use the WebSocket API, or serve your page from Muxit itself.</p><p>A reverse proxy in front of Muxit also changes the address the browser sees. Muxit does not read <code>X-Forwarded-*</code> headers. A proxy that passes its own name through as the <code>Host</code> is refused until that name is in <a href="#host-names"><code>security.hostnames</code></a>; one that rewrites the <code>Host</code> to <code>127.0.0.1</code> gets through the host check but has its writes refused, because the browser&#39;s <code>Origin</code> no longer matches. And, separately, a proxy on the same machine makes every visitor look local to Muxit. Prefer Tailscale (below) over a proxy.</p><h2 id="internet-access-via-tailscale" tabindex="-1">Internet Access via Tailscale <a class="header-anchor" href="#internet-access-via-tailscale" aria-label="Permalink to &quot;Internet Access via Tailscale&quot;">​</a></h2><p>For accessing your lab from outside your network, we recommend <a href="https://tailscale.com" target="_blank" rel="noreferrer">Tailscale</a>:</p><ol><li>Install Tailscale on the Muxit server and your remote device</li><li>Join both to the same Tailscale network (free for personal use)</li><li>Enable Remote Access in Muxit Settings</li><li>Access Muxit via <code>http://&lt;tailscale-ip&gt;:8765</code></li></ol><p>Tailscale provides WireGuard encryption, so HTTPS is not needed.</p><p>The Tailscale IP works as is. To use the MagicDNS name instead (<code>http://lab-pc.tail1234.ts.net:8765</code>), or to put Muxit behind <code>tailscale serve</code>, add that name to <a href="#host-names"><code>security.hostnames</code></a>. The short name (<code>http://lab-pc:8765</code>) is this machine&#39;s host name, which is already allowed.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>&quot;Remote access is not enabled&quot; error:</strong> Enable Remote Access in Settings and restart the server.</p><p><strong>&quot;This server does not answer to the host name …&quot; (<code>HOST_NOT_ALLOWED</code>):</strong> You reached Muxit by a name it does not know is its own — usually a Tailscale MagicDNS name, a tunnel, or a reverse proxy. Add the name from the message to <a href="#host-names"><code>security.hostnames</code></a> and restart. The server&#39;s log shows each refused name once a minute.</p><p><strong>&quot;Remote access has no password yet&quot; (<code>REMOTE_PASSWORD_NOT_SET</code>):</strong> Set a password under <strong>Settings &gt; Remote Access</strong> on the server machine (open it at <code>http://localhost:8765</code> there).</p><p><strong>Can&#39;t connect from another computer:</strong></p><p>Open <strong>Settings → Server → Network Diagnostics</strong> in the Muxit UI. The panel shows:</p><ul><li>The address Muxit is actually bound to and whether Kestrel&#39;s TCP listener is up.</li><li>Your network interfaces and which ones mDNS advertises on.</li><li>On Windows: the active firewall profile, whether an allow rule covers your port, and any <code>Block</code> rules for <code>muxit</code> that override <code>Allow</code> rules.</li><li>mDNS query/answer counters (if the counter stays at 0 while a remote device tries to reach you, packets aren&#39;t arriving — usually a router AP-isolation setting or a firewall).</li><li>Copy-paste PowerShell fix commands for the common Windows issues (add allow rule for the port, delete stale block rules, set the active network profile to Private).</li></ul><p>The same data is available as JSON at <code>GET /api/diagnostics/network</code> if you want to curl it from the problem device.</p><p>Common causes, in rough order of frequency:</p><ol><li><strong>Windows network category is Public</strong> — the default firewall profile blocks most inbound connections. Either change the network to Private (<code>Set-NetConnectionProfile -InterfaceAlias &quot;Wi-Fi&quot; -NetworkCategory Private</code>) or add a port-based allow rule: <code>New-NetFirewallRule -DisplayName &quot;Muxit Server 8765&quot; -Direction Inbound -Protocol TCP -LocalPort 8765 -Profile Any -Action Allow</code> (run in elevated PowerShell).</li><li><strong>A leftover Windows Firewall Block rule</strong> for <code>muxit.exe</code> overrides any Allow rules. Delete it: <code>Get-NetFirewallRule -DisplayName &quot;*muxit*&quot; | Where-Object Action -eq Block | Remove-NetFirewallRule</code>.</li><li><strong>Router &quot;client isolation&quot; or guest Wi-Fi</strong> — many consumer routers block client-to-client traffic on guest SSIDs. Put the problem device on the main SSID or disable isolation in router admin.</li><li><strong>Phone connected to a different SSID/VLAN</strong> than the server PC. Check that both show IPs on the same subnet.</li><li><strong>Kestrel port binding conflict</strong> — if the diagnostics panel shows <code>TCP listener: NO — Kestrel did not bind</code>, another process (IIS, Skype, a previous Muxit run) is holding the port. <code>netstat -ano | findstr :&lt;port&gt;</code> finds the owner.</li><li><strong>HTTPS enabled, client using <code>http://</code></strong> — when <code>security.https: true</code>, Kestrel speaks only TLS on its listener. A plain <code>http://</code> request gets a <code>ERR_CONNECTION_ABORTED</code>. Use <code>https://</code> from every client, or disable HTTPS.</li></ol><p><strong>Forgot password:</strong> Delete <code>workspace/config/security.json</code> on the server machine and restart.</p><p><strong>Browser shows certificate warning (HTTPS):</strong> Expected with self-signed certificates. Click through the warning once per browser.</p><h2 id="mobile-access" tabindex="-1">Mobile Access <a class="header-anchor" href="#mobile-access" aria-label="Permalink to &quot;Mobile Access&quot;">​</a></h2><p>Muxit includes a touch-optimized mobile interface that activates automatically on screens narrower than 768px (phones and small tablets in portrait). When you open Muxit in a mobile browser, you&#39;ll see a simplified five-tab layout:</p><table tabindex="0"><thead><tr><th>Tab</th><th>What It Does</th></tr></thead><tbody><tr><td><strong>Dashboards</strong></td><td>View live dashboard widgets in a vertical flow layout. Swipe between dashboards using the pill bar.</td></tr><tr><td><strong>Devices</strong></td><td>Accordion list of connectors with live state values. Tap a property to edit writable values. Trigger actions with buttons.</td></tr><tr><td><strong>Chat</strong></td><td>Full-screen AI chat with voice input. Same AI capabilities as the desktop chat sidebar.</td></tr><tr><td><strong>Scripts</strong></td><td>Start/stop scripts and view log output with per-script filtering.</td></tr><tr><td><strong>More</strong></td><td>Server status, license info, recent error alerts, and a &quot;Switch to Desktop&quot; option.</td></tr></tbody></table><p>A floating microphone button provides voice input from any tab.</p><h3 id="force-desktop-mode" tabindex="-1">Force Desktop Mode <a class="header-anchor" href="#force-desktop-mode" aria-label="Permalink to &quot;Force Desktop Mode&quot;">​</a></h3><p>If you prefer the full desktop interface on a mobile device, tap <strong>More &gt; Switch to Desktop</strong>. To return to the mobile view, clear <code>muxit-force-desktop</code> from your browser&#39;s localStorage.</p>`,86)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
